// 本 TU 显式声明边界值，避免依赖共享头的偶然包含顺序。
namespace hanmo::resident { struct BoundaryValue; }
#include "state_need_period.hpp"
#include "affairs_model.hpp"
#include <limits>
namespace hanmo::resident {namespace {
bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
bool same(const StateNeedRef&a,const StateNeedRef&b){return a.need_id==b.need_id&&a.episode==b.episode;}
bool active(const StateNeed&n){return n.phase==StateNeedPhase::open||n.phase==StateNeedPhase::claimed;}
bool occupied(const StateNeedClaim&c){return c.phase==StateClaimPhase::accepted||c.phase==StateClaimPhase::performing;}
bool catalog_equal(const CatalogIdentity&a,const CatalogIdentity&b){return a.content_id==b.content_id&&a.content_version==b.content_version&&a.content_digest==b.content_digest&&a.ruleset_id==b.ruleset_id&&a.schema_sha256==b.schema_sha256&&a.pack_set_digest==b.pack_set_digest&&a.module_versions==b.module_versions&&a.artifact_sha256==b.artifact_sha256;}
Status period_shape(const ExactPeriodContext&p){auto whole=compare_fractions(p.opening_at.sub_half_day,CanonicalFraction{});if(!whole.ok)return {false,{},whole.error};if(p.period_id.empty()||whole.value||p.opening_at.half_day_tick<0||p.opening_at.half_day_tick==std::numeric_limits<Integer>::max()||p.through_tick!=p.opening_at.half_day_tick+1)return common_failure("InvalidStateNeedOriginalPeriod",p.period_id);return common_success();}
Status frozen_need(const StateNeedState&s,const StateNeedDeadlineOpening&f,const StateNeedPolicyRead&policies,const StateTaskRead&tasks){const auto*n=s.needs.find(f.need_ref.need_id);if(!n||!same({n->need_id,n->episode},f.need_ref))return common_failure("StateNeedOpeningReferenceMissing",f.need_ref.need_id);auto policy=policies.state_need_policy(n->goal_ref);if(!policy.ok)return {false,{},policy.error};if(!policy.value||f.rule_ref.rule_ref!=policy.value->id||!catalog_equal(f.rule_ref.catalog_identity,policies.state_need_catalog_identity()))return common_failure("StateNeedOpeningRuleMismatch",n->need_id);if(f.claim){const auto*c=s.claims.find(f.claim->claim_id);if(!c||!same(c->need_ref,f.need_ref)||c->task_contract_id!=f.claim->task_contract_id||!same(c->acceptance_ref,f.claim->acceptance_ref))return common_failure("StateNeedOpeningClaimMismatch",n->need_id);auto accepted=tasks.read_state_acceptance(c->acceptance_ref);if(!accepted.ok)return {false,{},accepted.error};if(accepted.value.contract_id!=c->task_contract_id||!same(accepted.value.need_ref,c->need_ref))return common_failure("StateNeedOpeningTaskMismatch",c->claim_id);}return common_success();}
}
Status validate_state_need_claim_window(const StateNeedState&s,Integer until,const WorldMoment&actual,const ExactPeriodContext*period){
 auto until_order=compare_world_moments(actual,{until,{}});if(!until_order.ok)return {false,{},until_order.error};if(until_order.value>=0)return common_failure("StateNeedClosed",{},ErrorKind::rule);
 if(!s.exact_period_openings)return period?common_failure("UnexpectedStateNeedExactPeriod"):common_success();
 if(period){auto valid=period_shape(*period);if(!valid.ok)return valid;const auto*o=s.period_openings.find(period->period_id);if(!o||o->through_tick!=period->through_tick)return common_failure("StateNeedOpeningMissing",period->period_id);auto same_open=compare_world_moments(o->opened_at,period->opening_at),from=compare_world_moments(period->opening_at,actual),to=compare_world_moments(actual,{period->through_tick,{}});if(!same_open.ok)return {false,{},same_open.error};if(!from.ok)return {false,{},from.error};if(!to.ok)return {false,{},to.error};if(same_open.value||from.value>0||to.value>0)return common_failure("StateNeedClaimPeriodMismatch",period->period_id);
 // Accepted after capture is never an opening participant. Its first possible
 // service is in a later opening; this check supplies no service or completion.
 if(until<=period->through_tick)return common_failure("StateClaimNoFutureServiceWindow",{},ErrorKind::rule);return common_success();}
 auto whole=compare_fractions(actual.sub_half_day,CanonicalFraction{});if(!whole.ok)return {false,{},whole.error};if(whole.value)return common_failure("StateNeedOriginalOpenPeriodRequired");for(const auto&row:s.period_openings.rows()){auto a=compare_world_moments(row.second.opened_at,actual),b=compare_world_moments(actual,{row.second.through_tick,{}});if(!a.ok)return {false,{},a.error};if(!b.ok)return {false,{},b.error};if(a.value<=0&&b.value<0)return common_failure("StateNeedOriginalOpenPeriodRequired",row.first);}return common_success();
}
Status open_state_need_period(StateNeedState&s,const ExactPeriodContext&p,const StateNeedPolicyRead&policies,const StateTaskRead&tasks){
 if(!s.exact_period_openings)return common_failure("StateNeedOpeningProfile2Required");auto valid=period_shape(p);if(!valid.ok)return valid;if(s.period_openings.find(p.period_id))return validate_state_need_period(s,p,false,policies,tasks);
 StateNeedPeriodOpening opening;opening.period_id=p.period_id;opening.opened_at=p.opening_at;opening.through_tick=p.through_tick;
 for(const auto&row:s.needs.rows()){const auto&n=row.second;if(!active(n))continue;auto policy=policies.state_need_policy(n.goal_ref);if(!policy.ok)return {false,{},policy.error};if(!policy.value||policy.value->id.empty())return common_failure("StateNeedOpeningPolicyRequired",row.first);StateNeedDeadlineOpening item;item.need_ref={n.need_id,n.episode};item.rule_ref={policies.state_need_catalog_identity(),policy.value->id};if(n.active_claim_id){const auto*c=s.claims.find(*n.active_claim_id);if(!c||!occupied(*c)||!same(c->need_ref,item.need_ref))return common_failure("StateNeedOpeningClaimMismatch",row.first);item.claim=StateNeedOpeningClaim{c->claim_id,c->task_contract_id,c->acceptance_ref};}valid=frozen_need(s,item,policies,tasks);if(!valid.ok)return valid;opening.opening_needs.push_back(std::move(item));}
 if(!s.period_openings.insert(p.period_id,std::move(opening)))return common_failure("DuplicateStateNeedOpening",p.period_id);return common_success();
}
Status validate_state_need_period(const StateNeedState&s,const ExactPeriodContext&p,bool closed,const StateNeedPolicyRead&policies,const StateTaskRead&tasks){
 if(!s.exact_period_openings)return common_failure("StateNeedOpeningProfile2Required");auto valid=period_shape(p);if(!valid.ok)return valid;const auto*opening=s.period_openings.find(p.period_id);if(!opening||opening->period_id!=p.period_id||opening->through_tick!=p.through_tick)return common_failure("StateNeedOpeningMissing",p.period_id);auto at=compare_world_moments(opening->opened_at,p.opening_at);if(!at.ok)return {false,{},at.error};if(at.value)return common_failure("StateNeedOpeningMomentMismatch",p.period_id);
 for(std::size_t i=0;i<opening->opening_needs.size();++i){const auto&item=opening->opening_needs[i];for(std::size_t j=0;j<i;++j)if(opening->opening_needs[j].need_ref.need_id==item.need_ref.need_id)return common_failure("DuplicateStateNeedOpeningReference",item.need_ref.need_id);valid=frozen_need(s,item,policies,tasks);if(!valid.ok)return valid;const auto*n=s.needs.find(item.need_ref.need_id);if(n->opened_tick>p.opening_at.half_day_tick)return common_failure("LateNeedInOpening",n->need_id);if(closed&&n->deadline&&n->deadline->tick<=p.through_tick&&active(*n))return common_failure("UnclosedOpeningStateNeedDeadline",n->need_id);if(item.claim){const auto*c=s.claims.find(item.claim->claim_id);if(c->accepted_tick>p.opening_at.half_day_tick)return common_failure("LateClaimInOpening",c->claim_id);if(closed&&c->claim_until_tick<=p.through_tick&&occupied(*c))return common_failure("UnclosedOpeningStateClaimDeadline",c->claim_id);}}
 return common_success();
}
Status close_state_need_period(CommonStore&common,AffairsState&affairs,const ExactPeriodContext&p,const StateNeedPolicyRead&policies,const StateGoalRead&goals,StateTaskConsumer&tasks,const WorldMoment&actual){if(!affairs.state_needs)return common_failure("StateNeedCapabilityRequired");auto equal=compare_world_moments(actual,{p.through_tick,{}});if(!equal.ok)return {false,{},equal.error};if(equal.value)return common_failure("StateNeedClosingMomentMismatch",p.period_id);auto valid=validate_state_need_period(*affairs.state_needs,p,false,policies,tasks);if(!valid.ok)return valid;const auto*opening=affairs.state_needs->period_openings.find(p.period_id);valid=close_state_need_deadlines(common,affairs,opening->opening_needs,policies,goals,tasks,actual);if(!valid.ok)return valid;valid=reconcile_state_affair_closure(common,affairs,tasks,actual);if(!valid.ok)return valid;return validate_state_need_period(*affairs.state_needs,p,true,policies,tasks);}
Status validate_state_need_period_history(const StateNeedState&s,const WorldTimelineState&timeline,const WorldMoment&actual,const StateNeedPolicyRead&policies,const StateTaskRead&tasks){if(!s.exact_period_openings)return common_failure("StateNeedOpeningProfile2Required");for(const auto&row:s.period_openings.rows()){const auto&o=row.second;if(row.first!=o.period_id)return common_failure("StateNeedOpeningKeyMismatch",row.first);auto past=compare_world_moments(o.opened_at,actual);if(!past.ok)return {false,{},past.error};if(past.value>0)return common_failure("FutureStateNeedOpening",row.first);const bool live=timeline.period_id==row.first&&timeline.boundary_state==PeriodBoundaryState::open;auto through=compare_world_moments({o.through_tick,{}},actual);if(!through.ok)return {false,{},through.error};if(!live&&through.value>0)return common_failure("UnfinishedNonCurrentStateNeedOpening",row.first);auto valid=validate_state_need_period(s,{o.period_id,o.opened_at,o.through_tick},!live,policies,tasks);if(!valid.ok)return valid;}if(timeline.boundary_state==PeriodBoundaryState::open&&!s.period_openings.find(timeline.period_id))return common_failure("StateNeedCurrentOpeningMissing",timeline.period_id);
 // Every retained deadline result is tied back to the actual frozen opening.
 for(const auto&row:s.deadline_closures.rows()){const auto&c=row.second;std::size_t matches=0;for(const auto&opening:s.period_openings.rows())if(opening.second.through_tick==c.deadline_closed_at_tick)for(const auto&item:opening.second.opening_needs)if(same(item.need_ref,{c.need_id,c.episode})&&(!c.claim_id||(item.claim&&item.claim->claim_id==*c.claim_id)))++matches;if(matches!=1)return common_failure("StateNeedDeadlineOpeningCoverageMismatch",row.first);}
 return common_success();}
Outcome<WorldMoment> read_state_need_period_opening(const StateNeedState&s,const SourceRef&ref,Integer schema){if(schema!=1||ref.domain!="affairs"||ref.kind!="state_need_period_open")return {false,{},common_failure("StateNeedPeriodSourceRequired",ref.id).error};const auto*o=s.period_openings.find(ref.id);if(!s.exact_period_openings||!o||o->period_id!=ref.id)return {false,{},common_failure("StateNeedOpeningMissing",ref.id).error};auto valid=period_shape({o->period_id,o->opened_at,o->through_tick});if(!valid.ok)return {false,{},valid.error};return {true,o->opened_at,{}};}
Outcome<bool> state_need_opening_releasable(const StateNeedState&s,const StableId&id,const WorldTimelineState&timeline,const WorldMoment&actual){const auto*o=s.period_openings.find(id);if(!o)return {false,false,common_failure("StateNeedOpeningMissing",id).error};if(id==timeline.period_id)return {true,false,{}};auto ended=compare_world_moments({o->through_tick,{}},actual);if(!ended.ok)return {false,false,ended.error};if(ended.value>0)return {true,false,{}};for(const auto&row:s.deadline_closures.rows())if(row.second.deadline_closed_at_tick==o->through_tick)for(const auto&n:o->opening_needs)if(row.second.need_id==n.need_ref.need_id&&row.second.episode==n.need_ref.episode)return {true,false,{}};return {true,true,{}};}
}
